Select TOP (5) GetDate() as Now, cast(o.Total AS decimal(10, 2)) as Total, CAST(o.Qty as INT) as Qty, Upper(o.Status) as Status, @@RowCount as Rows
From dbo.Orders as o
where o.OrderDate >= DateAdd(day, -7, SysDateTime());

